        var course = post.getCoursePostingBelongsTo();
        if (course == null) {
            throw new IllegalStateException("Course is null for post " + post.getId());
        }

        // Resolve the exercise the post relates to (if any) and build the corresponding exercise DTO for the pipeline.
        Optional<PyrisTextExerciseDTO> textExerciseDTO = Optional.empty();
        Optional<PyrisProgrammingExerciseDTO> programmingExerciseDTO = Optional.empty();
        var exercise = post.getConversation() instanceof Channel channel ? channel.getExercise() : null;
        if (exercise != null) {
            switch (exercise.getExerciseType()) {
                case PROGRAMMING -> {
                    var programmingExercise = programmingExerciseRepository.findByIdWithTemplateAndSolutionParticipationElseThrow(exercise.getId());
                    programmingExerciseDTO = Optional.of(pyrisDTOService.toPyrisProgrammingExerciseDTO(programmingExercise));
                }
                case TEXT -> {
                    var textExercise = textRepositoryApi.orElseThrow(() -> new TextApiNotPresentException(TextApi.class)).findByIdElseThrow(exercise.getId());
                    textExerciseDTO = Optional.of(PyrisTextExerciseDTO.of(textExercise));
                }
                default -> {
                    // Other exercise types are currently not supported for tutor suggestions
                }
            }
        }

        var finalTextExerciseDTO = textExerciseDTO;
        var finalProgrammingExerciseDTO = programmingExerciseDTO;
        // @formatter:off
        executePipeline(
            "tutor-suggestion",
            variant,
            eventVariant,
            pyrisJobService.addTutorSuggestionJob(post.getId(), course.getId(), session.getId()),
            executionDto -> {
                var user = userRepository.findByIdElseThrow(session.getUserId());
                return new PyrisTutorSuggestionPipelineExecutionDTO(
                    new PyrisCourseDTO(course),
                    Optional.empty(),
                    new PyrisPostDTO(post),
                    pyrisDTOService.toPyrisMessageDTOList(session.getMessages()),
                    new PyrisUserDTO(user),
                    executionDto.settings(),
                    executionDto.initialStages(),
                    finalTextExerciseDTO,
                    finalProgrammingExerciseDTO
                );
            },
            stages -> irisChatWebsocketService.sendStatusUpdate(session, stages)
        );
