 *
 * @param id      post id
 * @param content content of the post
 * @param answers answers to the post
 */
@JsonInclude(JsonInclude.Include.NON_EMPTY)
public record PyrisPostDTO(Long id, String content, Set<PyrisAnswerPostDTO> answers, Long userID) {

